from taf.fdsw.rc.interfaces.FDSW21C.fdsw import FDSW21C
from taf.fdsw.rc.interfaces.FDSW21D.autoconnection import AutoConfiguration21D
from taf.fdsw.rc.interfaces.FDSW21D.security import Security21D
from taf.fdsw.rc.interfaces.FDSW21D.swm import SoftwareManagement21D


class FDSW21D(FDSW21C):
    VERSION_NAME = 'FDSW21D'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW21D, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)

        self.swm = SoftwareManagement21D(client=self._client)
        self.autoconnection = AutoConfiguration21D(client=self._client)
        self.security = Security21D(client=self._client)
